CREATE TABLE airports (id BIGSERIAL PRIMARY KEY, code VARCHAR(3) NOT NULL UNIQUE, city VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, country VARCHAR(255) NOT NULL);
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL CHECK (role IN ('USER','ADMIN')));
CREATE TABLE flights (id BIGSERIAL PRIMARY KEY, flight_number VARCHAR(255) NOT NULL, origin_id BIGINT NOT NULL REFERENCES airports, destination_id BIGINT NOT NULL REFERENCES airports, departure_time TIMESTAMPTZ NOT NULL, arrival_time TIMESTAMPTZ NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), aircraft VARCHAR(255) NOT NULL, UNIQUE(flight_number,departure_time), CHECK(origin_id<>destination_id), CHECK(arrival_time>departure_time));
CREATE INDEX idx_flights_search ON flights(origin_id,destination_id,departure_time);
CREATE TABLE fare_classes (id BIGSERIAL PRIMARY KEY, code VARCHAR(255) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, benefits VARCHAR(255) NOT NULL, baggage_kg INTEGER NOT NULL, seat_included BOOLEAN NOT NULL);
CREATE TABLE flight_fares (id BIGSERIAL PRIMARY KEY, flight_id BIGINT NOT NULL REFERENCES flights, fare_class_id BIGINT NOT NULL REFERENCES fare_classes, price NUMERIC(14,2) NOT NULL CHECK(price>=0), UNIQUE(flight_id,fare_class_id));
CREATE TABLE bookings (id BIGSERIAL PRIMARY KEY, code VARCHAR(255) UNIQUE NOT NULL, access_token UUID UNIQUE NOT NULL, status VARCHAR(255) NOT NULL CHECK(status IN ('PENDING','CONFIRMED','CANCELLED','EXPIRED')), contact_email VARCHAR(255) NOT NULL, contact_phone VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, base_amount NUMERIC(14,2) NOT NULL, tax_amount NUMERIC(14,2) NOT NULL, extras_amount NUMERIC(14,2) NOT NULL, discount_amount NUMERIC(14,2) NOT NULL, total_amount NUMERIC(14,2) NOT NULL CHECK(total_amount>=0), promotion_code VARCHAR(255), user_id BIGINT REFERENCES users);
CREATE INDEX idx_bookings_expiry ON bookings(status,expires_at);
CREATE TABLE booking_segments (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES bookings, flight_id BIGINT NOT NULL REFERENCES flights, fare_class_id BIGINT NOT NULL REFERENCES fare_classes, segment_index INTEGER NOT NULL, seated_passengers INTEGER NOT NULL CHECK(seated_passengers>0), unit_price NUMERIC(14,2) NOT NULL, UNIQUE(booking_id,segment_index), UNIQUE(booking_id,flight_id));
CREATE INDEX idx_segments_flight ON booking_segments(flight_id,booking_id);
CREATE TABLE passengers (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES bookings, passenger_index INTEGER NOT NULL, type VARCHAR(255) NOT NULL CHECK(type IN ('ADULT','CHILD','INFANT')), title VARCHAR(255) NOT NULL, last_name VARCHAR(255) NOT NULL, first_name VARCHAR(255) NOT NULL, date_of_birth DATE NOT NULL, nationality VARCHAR(255) NOT NULL, UNIQUE(booking_id,passenger_index));
CREATE TABLE flight_seats (id BIGSERIAL PRIMARY KEY, flight_id BIGINT NOT NULL REFERENCES flights, seat_number VARCHAR(255) NOT NULL, extra_legroom BOOLEAN NOT NULL, price NUMERIC(14,2) NOT NULL CHECK(price>=0), booking_id BIGINT REFERENCES bookings, passenger_index INTEGER, blocked BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(flight_id,seat_number), CHECK((booking_id IS NULL)=(passenger_index IS NULL)));
CREATE UNIQUE INDEX idx_seat_passenger ON flight_seats(flight_id,booking_id,passenger_index) WHERE booking_id IS NOT NULL;
CREATE TABLE ancillary_services (id BIGSERIAL PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, category VARCHAR(255) NOT NULL, description VARCHAR(255) NOT NULL, price NUMERIC(14,2) NOT NULL CHECK(price>=0));
CREATE TABLE booking_ancillaries (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES bookings, flight_id BIGINT NOT NULL REFERENCES flights, service_id BIGINT NOT NULL REFERENCES ancillary_services, passenger_index INTEGER NOT NULL, price NUMERIC(14,2) NOT NULL, UNIQUE(booking_id,flight_id,service_id,passenger_index));
CREATE TABLE payments (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES bookings, request_key UUID NOT NULL UNIQUE, status VARCHAR(255) NOT NULL CHECK(status IN ('SUCCESS','FAILED','CANCELLED')), amount NUMERIC(14,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE UNIQUE INDEX idx_payment_success ON payments(booking_id) WHERE status='SUCCESS';
CREATE TABLE promotion_codes (id BIGSERIAL PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE, percent INTEGER NOT NULL CHECK(percent BETWEEN 1 AND 100), max_discount NUMERIC(14,2) NOT NULL, expires_on DATE NOT NULL);
CREATE TABLE content_items (id BIGSERIAL PRIMARY KEY, category VARCHAR(255) NOT NULL, title VARCHAR(255) NOT NULL, description VARCHAR(2000) NOT NULL, image VARCHAR(255) NOT NULL, target VARCHAR(255) NOT NULL, sort_order INTEGER NOT NULL);
CREATE TABLE check_ins (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES bookings, flight_id BIGINT NOT NULL REFERENCES flights, passenger_index INTEGER NOT NULL, seat_number VARCHAR(255) NOT NULL, boarding_code VARCHAR(255) NOT NULL UNIQUE, checked_in_at TIMESTAMPTZ NOT NULL, UNIQUE(booking_id,flight_id,passenger_index), UNIQUE(flight_id,seat_number));
